/**
 * Checks the 3D model (model/altair-8800.glb) against what the page
 * relies on in it, and against the params it was built from
 * (docs/3d-model.md, Part 2). The model is generated by Blender, which
 * CI does not have, so this is what catches a model that was rebuilt
 * from changed params and not committed, or one that lost a node the
 * page binds.
 *
 * The .glb is read as glTF JSON: no three.js, so the suite stays
 * dependency-free.
 *
 * Run with: npm test
 */
'use strict';

import test from 'node:test';
import assert from 'node:assert';
import fs from 'node:fs';
import path from 'node:path';
import {panel} from '../js/app.js';
import {readGlb} from './glb.js';

const ROOT = path.join(import.meta.dirname, '..');
const GLB = path.join(ROOT, 'model', 'altair-8800.glb');
const PARAMS = JSON.parse(fs.readFileSync(
    path.join(ROOT, 'model', 'params', 'machine.json'), 'utf8'));

const GLTF = readGlb(GLB);

/** Every node, by its name in the model (with its dots). */
const NODES = new Map(GLTF.nodes.map((node) => [node.name, node]));

/** The removable units: every node with a way out. */
const UNITS = Object.keys(PARAMS.paths.v);

/** The cards, as the model names them. */
const CARDS = ['cpu', 'mem1k', 'mem4k_0', 'mem4k_1', 'sio', 'sio2'];

/** The name three.js gives a node on load (PropertyBinding's rule). */
function sanitised(name) {
    return name.replace(/\s/g, '_').replace(/[\[\]\.:\/]/g, '');
}

test('the model has a lamp for every lamp on the 2D panel', () => {
    for (const led of panel.LED_INFO) {
        const node = NODES.get('panel.lamp.' + led.id);
        assert.ok(node, 'panel.lamp.' + led.id);
        assert.strictEqual(node.extras.motion, 'lamp');
        assert.strictEqual(node.extras.lamp_id, led.id);
    }
    const lamps = GLTF.nodes.filter((node) => node.name.startsWith('panel.lamp.'));
    assert.strictEqual(lamps.length, panel.LED_INFO.length);
});

test('the model has a switch for every switch on the 2D panel', () => {
    const ids = panel.TOGGLE_SWITCH_INFO.concat(panel.STATELESS_SWITCH_INFO)
          .map((info) => info.id);
    assert.strictEqual(ids.length, 25);
    for (const id of ids) {
        const name = 'panel.switch.' + id.replace('-', '_');
        const node = NODES.get(name);
        assert.ok(node, name);
        assert.strictEqual(node.extras.switch_id, id);
        assert.strictEqual(node.extras.motion, 'rotate');
        assert.strictEqual(node.extras.throw_deg, PARAMS.switch.throw.v);
        const momentary = panel.STATELESS_SWITCH_INFO.some((info) => info.id === id);
        assert.strictEqual(node.extras.kind, momentary ? 'momentary' : 'latching', id);
    }
});

test('every card has its slot and its card node, lifting straight up', () => {
    for (const card of CARDS) {
        const slot = NODES.get('slot.' + card);
        const node = NODES.get('card.' + card);
        assert.ok(slot && node, card);
        assert.deepStrictEqual(slot.extras.axis, [1, 0, 0], card + ': its slot moves along X');
        assert.deepStrictEqual(node.extras.axis, [0, 1, 0], card + ': it lifts up (glTF Y)');
        assert.ok(node.extras.role, card + ' says what it does');
        // The card hangs from its slot, so a slot carries it to another one.
        const index = GLTF.nodes.indexOf(node);
        assert.ok((slot.children || []).includes(index), card + ' is the child of its slot');
    }
});

test('every unit has the way out and the prerequisites its params give', () => {
    for (const unit of UNITS) {
        const node = NODES.get(unit);
        assert.ok(node, unit);
        assert.strictEqual(node.extras.motion, 'path', unit);
        // Params give moves in the machine frame (Z up, mm); the model gives
        // the points they reach, in glTF's frame (Y up): (x, z, -y).
        const points = [0, 0, 0];
        let at = [0, 0, 0];
        for (const [x, y, z] of PARAMS.paths.v[unit]) {
            at = [at[0] + x, at[1] + z, at[2] - y];
            points.push(...at);
        }
        assert.deepStrictEqual(node.extras.path.map((v) => v + 0), points.map((v) => v + 0), unit);
        const prereqs = node.extras.prereqs ? node.extras.prereqs.split(',') : [];
        assert.deepStrictEqual(prereqs, PARAMS.prereqs.v[unit], unit);
    }
});

test('the model was built from the params in the repository', () => {
    const root = GLTF.nodes.find((node) => node.extras && node.extras.params_version);
    assert.ok(root);
    assert.strictEqual(root.extras.params_version, PARAMS.version,
                       'rebuild the model (npm run build:model) after changing its params');
    assert.strictEqual(root.extras.build, 'whole box');
});

test('every part says what it is, and no two names meet once three.js loads them', () => {
    const seen = new Map();
    for (const node of GLTF.nodes) {
        if (node.extras && node.extras.params_version) {
            continue;
        }
        assert.ok(node.extras && node.extras.label_en, node.name + ' has a label');
        const name = sanitised(node.name);
        assert.ok(!seen.has(name), node.name + ' and ' + seen.get(name) + ' collide');
        seen.set(name, node.name);
    }
});

test('the model keeps within its budgets', () => {
    const bytes = fs.statSync(GLB).size;
    assert.ok(bytes < 5 * 1024 * 1024, 'under 5 MB for plain git, is ' + bytes);
    let triangles = 0;
    for (const mesh of GLTF.meshes) {
        for (const primitive of mesh.primitives) {
            assert.strictEqual(primitive.mode === undefined ? 4 : primitive.mode, 4);
            const accessor = primitive.indices !== undefined ?
                  GLTF.accessors[primitive.indices] :
                  GLTF.accessors[primitive.attributes.POSITION];
            triangles += accessor.count / 3;
        }
    }
    // Instanced meshes count once per node that uses them.
    const uses = new Map();
    for (const node of GLTF.nodes) {
        if (node.mesh !== undefined) {
            uses.set(node.mesh, (uses.get(node.mesh) || 0) + 1);
        }
    }
    assert.ok([...uses.values()].every((n) => n === 1), 'no shared meshes');
    assert.ok(triangles < 300000, 'under 300 k triangles, is ' + triangles);
});
